def make_maps()->Tuple[Dict[Tuple[str], str],Dict[Tuple[str], str]]:
    import json
    from typing import List, Dict, Tuple

    def split_vals(src:str, exclude_parts:List[str] = None, include_parts:List[str] = None)->Tuple[str]:
        if exclude_parts is None:
            exclude_parts = []
        x = src.split(',')
        x = [z.strip() for z in x]
        x = [z for z in x if z not in exclude_parts]
        if include_parts:
            x.extend([z for z in include_parts if z not in x])
        x = sorted(x)
        x = tuple(x)
        return x


    map_bb_to_datapoint:Dict[Tuple[str], str] = {}
    map_tb_gosb_to_deprt:Dict[Tuple[str, str]|Tuple[str], str] = {}



    for (hash, dic, bb, tb, gosb) in DATA:
        dic = json.loads(dic)
        print(dic)


        dp = dic.get('data_point', '')

        bb = split_vals(bb, ['Sberbank Int.', 'ДРПА', 'Прочие'], ['КИБ (Все)'] if dp == 'КИБ' else None)

        map_bb_to_datapoint[bb] = dp

        map_tb_gosb_to_deprt[(tb, gosb,)] = dic['deprt']


    return (map_bb_to_datapoint, map_tb_gosb_to_deprt)


def main():
    (m1, m2) = make_maps()
    print(m1)
    print(m2)



if __name__ == '__main__':
    main()